'use strict';
let serial=0,selected=0,activeTab='ball';
const leafShape='<path d="M13 43C7 23 26 10 55 9c0 27-15 44-34 40Z"/>';
const leafCut='<path d="M11 57 45 20m-17 17-2-11" fill="none" stroke="black" stroke-width="4.4" stroke-linecap="round"/>';
function roundPolygon(points,r=3){let pointsAround=points.map((p,i)=>{let prev=points[(i+points.length-1)%points.length],next=points[(i+1)%points.length],a=Math.hypot(prev[0]-p[0],prev[1]-p[1]),b=Math.hypot(next[0]-p[0],next[1]-p[1]);return {p,in:[p[0]+(prev[0]-p[0])*Math.min(.4,r/a),p[1]+(prev[1]-p[1])*Math.min(.4,r/a)],out:[p[0]+(next[0]-p[0])*Math.min(.4,r/b),p[1]+(next[1]-p[1])*Math.min(.4,r/b)]}});return '<path d="'+pointsAround.map((p,i)=>(i?'L':'M')+p.in.join(',')+'Q'+p.p.join(',')+' '+p.out.join(',')).join('')+'Z"/>'}
function gear(teeth){let points=[];for(let i=0;i<teeth;i++)for(let j=0;j<4;j++){let a=(i*4+j)*Math.PI*2/(teeth*4)-Math.PI/2,r=j===1||j===2?27:21;points.push([32+Math.cos(a)*r,32+Math.sin(a)*r])}return roundPolygon(points,2.8)}
function petals(){let result='<circle cx="32" cy="32" r="17"/>';for(let i=0;i<6;i++){let a=i*Math.PI/3;result+=`<circle cx="${32+Math.cos(a)*17}" cy="${32+Math.sin(a)*17}" r="11"/>`}return result}
const families=[
{title:'柔角实心',badge:'推荐 · 辨识清晰',note:'基础房屋与八齿设置，柔角轮廓加少量镂空。适合日常导航。',home:'<path d="m8 29 20-19q4-4 8 0l20 19q4 4-1 7l-3 1v16q0 6-6 6H18q-6 0-6-6V37l-3-1q-5-3-1-7Z"/>',homeCut:'<rect x="27" y="38" width="10" height="24" rx="5"/><path d="m17 30 14-13" fill="none" stroke="black" stroke-width="3.4" stroke-linecap="round"/>',settings:gear(8),settingsCut:'<circle cx="32" cy="32" r="9"/><path d="m16 49 5-5" fill="none" stroke="black" stroke-width="3.5" stroke-linecap="round"/>'},
{title:'叶脉切线',badge:'更接近原款',note:'把叶片的斜向切线带入屋顶与设置中心，让三枚图标更像一家。',home:'<path d="M9 32C10 18 29 10 48 8c9 10 10 18 6 26v18q0 7-7 7H18q-7 0-7-7V35Z"/>',homeCut:'<path d="M11 35 43 16m-13 8-3-8" fill="none" stroke="black" stroke-width="4" stroke-linecap="round"/><rect x="28" y="40" width="10" height="22" rx="5"/>',settings:gear(6),settingsCut:'<path d="M23 38C20 26 30 21 43 21c0 13-8 23-17 20Z"/><path d="m17 49 27-28" fill="none" stroke="black" stroke-width="3" stroke-linecap="round"/>'},
{title:'实心调节',badge:'工具感',note:'首页保留熟悉的房屋；设置改成实心调节杆，更轻、更易读。',home:'<path d="M5 30 28 9q4-4 8 0l23 21q3 4-3 5h-4v20q0 5-5 5H17q-5 0-5-5V35H8q-6-1-3-5Z"/>',homeCut:'<path d="M28 63V42q0-6 5-6t5 6v21Z"/>',settings:'<rect x="8" y="7" width="10" height="50" rx="5"/><rect x="27" y="7" width="10" height="50" rx="5"/><rect x="46" y="7" width="10" height="50" rx="5"/><circle cx="13" cy="24" r="10"/><circle cx="32" cy="42" r="10"/><circle cx="51" cy="20" r="10"/>',settingsCut:'<circle cx="13" cy="24" r="4.1"/><circle cx="32" cy="42" r="4.1"/><circle cx="51" cy="20" r="4.1"/>'},
{title:'圆润花瓣',badge:'更有亲和力',note:'弧形房屋搭配六瓣设置，体块圆润，适合柔和的绿色界面。',home:'<path d="M8 33Q9 20 27 9q5-3 10 0 18 11 19 24v16q0 11-11 11H19Q8 60 8 49Z"/>',homeCut:'<path d="M25 62V42q0-8 7-8t7 8v20Z"/><path d="m16 28 10-9" fill="none" stroke="black" stroke-width="3.5" stroke-linecap="round"/>',settings:petals(),settingsCut:'<circle cx="32" cy="32" r="9.5"/>'},
{title:'几何留白',badge:'克制清晰',note:'用大块留白代替细线，保留实心质感，也能在小尺寸下识别。',home:'<path d="m7 28 21-18q4-4 8 0l21 18q3 3 0 6l-4 3v15q0 7-7 7H18q-7 0-7-7V37l-4-3q-3-3 0-6Z"/>',homeCut:'<path d="M21 33 32 23l11 10v16h-7V38h-8v11h-7Z"/>',settings:roundPolygon([[32,4],[43,11],[55,14],[58,28],[54,43],[43,55],[29,60],[14,53],[7,40],[6,25],[15,12]],5),settingsCut:'<path d="M19 37C16 24 27 18 44 18c0 15-8 27-21 24Z"/><path d="m15 49 29-29" fill="none" stroke="black" stroke-width="3" stroke-linecap="round"/>'},
{title:'叶窗印记',badge:'品牌感',note:'首页以叶形窗强化小叶身份；设置采用粗齿环与斜切孔。',home:'<path d="M7 28 28 8q4-4 8 0l21 20q3 4-1 7l-3 1v17q0 7-7 7H18q-7 0-7-7V36l-3-1q-4-3-1-7Z"/>',homeCut:'<path d="M23 44C20 33 30 28 43 28c0 13-7 22-17 20Z"/><path d="m19 54 23-25" fill="none" stroke="black" stroke-width="2.8" stroke-linecap="round"/>',settings:gear(7),settingsCut:'<path d="M22 38c-2-10 6-17 20-17 0 12-7 21-17 19Z"/><path d="m18 47 26-27" fill="none" stroke="black" stroke-width="3.8" stroke-linecap="round"/>'}
];
function glyph(body,cuts,label){let id='cut-'+serial++;return `<svg viewBox="0 0 64 64" fill="currentColor" role="img" aria-label="${label}"><defs><mask id="${id}" maskUnits="userSpaceOnUse" x="0" y="0" width="64" height="64"><rect width="64" height="64" fill="white"/><g fill="black">${cuts}</g></mask></defs><g mask="url(#${id})">${body}</g></svg>`}
function leaf(){return glyph(leafShape,leafCut,'原叶片风格图标')}
function home(i){return glyph(families[i].home,families[i].homeCut,'首页图标')}
function settings(i){return glyph(families[i].settings,families[i].settingsCut,'设置图标')}
function renderCards(){document.querySelector('#gallery').innerHTML=families.map((f,i)=>`<button class="card ${selected===i?'selected':''}" data-family="${i}" aria-pressed="${selected===i}"><div class="card-header"><span class="card-title">0${i+1} · ${f.title}</span><span class="badge">${f.badge}</span></div><div class="card-icons"><div class="glyph">${home(i)}<span>首页</span></div><div class="glyph reference">${leaf()}<span>悬浮球 · 原款</span></div><div class="glyph">${settings(i)}<span>设置</span></div></div><p class="card-note">${f.note}</p><div class="card-mini">${home(i)}${leaf()}${settings(i)}<span class="mini-label">20 px</span></div></button>`).join('')}
function preview(){let f=families[selected];document.querySelector('#current-title').textContent='0'+(selected+1)+' · '+f.title;document.querySelector('#current-note').textContent=f.note;document.querySelector('#live-nav').innerHTML=[['home','首页',home(selected)],['ball','悬浮球',leaf()],['settings','设置',settings(selected)]].map(([key,label,svg])=>`<button class="nav-item ${activeTab===key?'active':''}" data-nav="${key}" aria-pressed="${activeTab===key}"><span class="pill">${svg}</span>${label}</button>`).join('');document.querySelector('#state-samples').innerHTML=[true,false].map(on=>`<div class="state-row"><span class="state-label">${on?'选中状态':'未选中'}</span>${[['首页',home(selected)],['悬浮球',leaf()],['设置',settings(selected)]].map(([label,svg])=>`<div class="state-sample ${on?'active':''}"><span class="pill">${svg}</span>${label}</div>`).join('')}</div>`).join('');document.querySelector('#size-samples').innerHTML=[18,22,28,36].map(n=>`<div class="size-pair"><div>${home(selected).replace('<svg ','<svg style="width:'+n+'px;height:'+n+'px" ')}${settings(selected).replace('<svg ','<svg style="width:'+n+'px;height:'+n+'px" ')}</div><small>${n} px</small></div>`).join('')}
document.addEventListener('click',e=>{let family=e.target.closest('[data-family]');if(family){selected=Number(family.dataset.family);renderCards();preview();return}let color=e.target.closest('[data-color]');if(color){document.documentElement.style.setProperty('--ink',color.dataset.color);document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('active',b===color));return}let nav=e.target.closest('[data-nav]');if(nav){activeTab=nav.dataset.nav;preview()}});
renderCards();preview();
